INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a64d6c7-0139-4f69-9271-c6030e584e25', '曉濟膠川南入密界', '晓济胶川南入密界', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u98f2\u99ac\u81a0\u5ddd\u4e0a\uff0c\u508d\u81a0\u5357\u8da3\u5bc6\u3002", "\u6797\u9059\u98db\u9ce5\u9072\uff0c\u96f2\u53bb\u6674\u5c71\u51fa\u3002", "\u843d\u6689\u96b1\u6851\u67d8\uff0c\u79cb\u539f\u88ab\u82b1\u5be6\u3002", "\u6158\u7136\u904a\u5b50\u5bd2\uff0c\u98a8\u9732\u5c07\u856d\u745f\u3002"]', '诗', 'shi', '', NULL, '曉濟膠川南入密界 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47ed0d19-9151-4877-824a-e71f85229c83', '夜發三泉即事', '夜发三泉即事', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u6697\u767c\u4e09\u6cc9\u5c71\uff0c\u7aae\u79cb\u807d\u9a37\u5c51\u3002", "\u5317\u6797\u591c\u9cf4\u96e8\uff0c\u5357\u671b\u66c9\u6210\u96ea\u3002", "\u7957\u8a60\u5317\u98a8\u6dbc\uff0c\u8a4e\u77e5\u5357\u571f\u71b1\u3002", "\u6c99\u6eaa\u5ffd\u6cb8\u6e2d\uff0c\u77f3\u9053\u4e4d\u660e\u6ec5\u3002", "\u5b9b\u82e5\u9280\u78e7\u6a6b\uff0c\u5fa9\u5982\u7464\u81fa\u7d50\u3002", "\u6307\u7a0b\u8ce6\u6240\u6200\uff0c\u9047\u865e\u4e0d\u9051\u6b47\u3002", "\u91cd\u7e8a\u6fe1\u83ab\u89e3\uff0c\u61f8\u65cc\u51cd\u7336\u63ed\u3002", "\u4e0b\u5954\u6ce5\u68e7\u69b0\uff0c\u4e0a\u89af\u96f2\u68af\u8a2d\u3002", "[\u640f]\u9830\u7fb8\u99ac\u9813\uff0c\u56de\u7738\u60f4\u4eba\u8dcc\u3002", "\u61a7\u61a7\u5f80\u5fa9\u9084\uff0c\u5fc3\u6ce8\u601d\u903e\u5207\u3002", "\u5189\u5189\u5e74\u5c07\u75c5\uff0c\u529b\u56f0\u8870\u6020\u7aed\u3002", "\u5929\u5f6d\u4fe1\u65b9\u9685\uff0c\u5730\u52e2\u8aa0\u6597\u7d55\u3002", "\u5fdd\u66f3\u5c1a\u66f8\u5c65\uff0c\u53e8\u517c\u4f7f\u81e3\u7bc0\u3002", "\u4eac\u577b\u6709\u6b72\u9952\uff0c\u4ead\u969c\u7121\u908a\u5b7d\u3002", "\u6b78\u594f\u4e39\u5880\u5de6\uff0c\u9a2b\u80fd\u4fdf\u4f86\u54f2\u3002"]', '诗', 'shi', '', NULL, '夜發三泉即事 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('caf2f7b9-372f-43f1-bbd1-3faabd0069b5', '小園納涼即事', '小园纳凉即事', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u7169\u6691\u907f\u84b8\u9b31\uff0c\u5c45\u9591\u7fd2\u9ad8\u660e\u3002", "\u9577\u98a8\u81ea\u9060\u4f86\uff0c\u5c64\u95a3\u6709\u9918\u6e05\u3002", "\u6563\u7051\u7d0d\u6dbc\u6c23\uff0c\u856d\u689d\u907a\u4e16\u60c5\u3002", "\u5948\u4f55\u8a87\u5927\u96b1\uff0c\u7d42\u65e5\u7e6b\u5875\u7e93\u3002"]', '诗', 'shi', '', NULL, '小園納涼即事 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a01e17f1-6dbc-4b4e-b859-ed698cdaf86c', '昆明池晏坐答王兵部珣三韻見示', '昆明池晏坐答王兵部珣三韵见示', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u756b\u8238\u75be\u5982\u98db\uff0c\u9059\u9059\u6c4e\u5915\u6689\u3002", "\u77f3\u9ee5\u5439\u6d6a\u96b1\uff0c\u7389\u5973\u6b65\u5875\u6b78\u3002", "\u7368\u6709\u929c\u6069\u8655\uff0c\u660e\u73e0\u5728\u91e3\u78ef\u3002"]', '诗', 'shi', '', NULL, '昆明池晏坐答王兵部珣三韻見示 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0e50379-1882-4fd1-9e61-9b63d0528b67', '題壽安王主簿池館', '题寿安王主簿池馆', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u6d1b\u9091\u901a\u99b3\u9053\uff0c\u97d3\u90ca\u5728\u5c6c\u57ce\u3002", "\u9928\u5c07\u82b1\u96e8\u6620\uff0c\u6f6d\u8207\u7af9\u8072\u6e05\u3002", "\u8ce2\u4fca\u9e1e\u68f2\u68d8\uff0c\u8cd3\u904a\u99ac\u4f69\u8861\u3002", "\u9858\u8a00\u96a8\u72ce\u9ce5\uff0c\u5f9e\u6b64\u6fef\u543e\u7e93\u3002"]', '诗', 'shi', '', NULL, '題壽安王主簿池館 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d69ab328-4934-4278-a54a-4a8169a6aef5', '扈從溫泉奉和姚令公喜雪', '扈从温泉奉和姚令公喜雪', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u6e05\u9053\u8c50\u4eba\u671b\uff0c\u4e58\u6642\u6f22\u4e3b\u904a\u3002", "\u6069\u6689\u96a8\u9730\u4e0b\uff0c\u6176\u6fa4\u8207\u96f2\u6d6e\u3002", "\u6cc9\u6696\u9a5a\u9280\u78e7\uff0c\u82b1\u5bd2\u611b\u7389\u6a13\u3002", "\u9f0e\u81e3\u4eca\u6709\u554f\uff0c\u6cb3\u4f2f\u4e14\u61c9\u7559\u3002"]', '诗', 'shi', '', NULL, '扈從溫泉奉和姚令公喜雪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1ed9973-1f11-4384-a1d3-41a5006446d6', '奉和聖製春臺望應制', '奉和圣制春台望应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u58ef\u9e97\u5929\u4e4b\u5e9c\uff0c\u795e\u660e\u738b\u8005\u5b85\u3002", "\u5927\u541b\u4e58\u98db\u9f8d\uff0c\u767b\u5f7c\u5fa9\u61f7\u6614\u3002", "\u5713\u95d5\u6731\u5149\u71c4\uff0c\u6a6b\u5c71\u7fe0\u5fae\u7a4d\u3002", "\u6cb3\u6c67\u6d41\u4f5c\u8868\uff0c\u7e23\u805a\u958b\u6210\u964c\u3002", "\u5373\u820a\u5728\u7687\u5bb6\uff0c\u7dad\u65b0\u5177\u7269\u83ef\u3002", "\u96f2\u9023\u6240\u4e0a\u5c45\u6046\u5c6c\uff0c\u65e5\u66f4\u6642\u4e2d\u671b\u4e0d\u659c\u3002", "\u4e09\u6708\u6ec4\u6c60\u6416\u7a4d\u6c34\uff0c\u842c\u5e74\u9752\u6a39\u7db4\u65b0\u82b1\u3002", "\u66b4\u5b34\u570b\u6b64\u5617\u5716\u9738\uff0c\u9738\u696d\u5f8c\u4ec1\u5148\u4ee5\u8a50\u3002", "\u6771\u7834\u8af8\u4faf\u897f\u5165\u79e6\uff0c\u54b8\u967d\u5317\u962a\u5357\u6e2d\u6d25\u3002", "\u8a69\u66f8\u711a\u7207\u6563\u5b78\u58eb\uff0c\u9ad8\u95a3\u5962\u8e30\u5b0c\u7f8e\u4eba\u3002", "\u4e8b\u5f80\u8986\u8f08\u7d93\u9060\u55bb\uff0c\u6625\u9084\u6309\u8e55\u6191\u9ad8\u8ce6\u3002", "\u620e\u89c0\u611b\u529b\u6df1\u60df\u7701\uff0c\u8d8a\u53ad\u9673\u65b9\u4f55\u8db3\u52d9\u3002", "\u6e05\u5439\u9059\u9059\u767c\u5e1d\u81fa\uff0c\u5bb8\u6587\u803f\u803f\u7167\u5929\u8ff4\u3002", "\u4f2f\u5937\u4f4d\u4e8b\u611a\u81e3\u5fdd\uff0c\u559c\u594f\u8072\u6210\u9cf3\u9ce5\u4f86\u3002"]', '诗', 'shi', '', NULL, '奉和聖製春臺望應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d89959e-48bf-48d4-a3c9-a945fb524c33', '長相思', '长相思', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u541b\u4e0d\u898b\u5929\u6d25\u6a4b\u4e0b\u6771\u6d41\u6c34\uff0c\u5357\u671b\u9f8d\u9580\u5317\u671d\u5e02\u3002", "\u694a\u67f3\u9752\u9752\u5b9b\u5730\u5782\uff0c\u6843\u7d05\u674e\u767d\u82b1\u53c3\u5dee\u3002", "\u82b1\u53c3\u5dee\uff0c\u67f3\u582a\u7d50\uff0c\u6b64\u6642\u61b6\u541b\u5fc3\u65b7\u7d55\u3002"]', '诗', 'shi', '', NULL, '長相思 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f15dddef-ce75-47cd-a516-a3058101d894', '蜀城哭台州樂安少府', '蜀城哭台州乐安少府', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u9060\u904a\u8e8b\u5292\u95a3\uff0c\u9577\u60f3\u5c6c\u5929\u53f0\u3002", "\u842c\u91cc\u9694\u4e09\u8f09\uff0c\u6b64\u90a6\u4f59\u91cd\u4f86\u3002", "\u97f3\u5bb9\u66e0\u4e0d\u89a9\uff0c\u5922\u5bd0\u6b8a\u60a0\u54c9\u3002", "\u908a\u90e1\u9952\u85c9\u85c9\uff0c\u665a\u5ead\u6b63\u56de\u56de\u3002", "\u559c\u50b3\u4e0a\u90fd\u5c01\uff0c\u56e0\u4fc3\u508d\u540f\u958b\u3002", "\u5411\u609f\u6d77\u9e7d\u5ba2\uff0c\u5df2\u800c\u6881\u6728\u6467\u3002", "\u8b8a\u8863\u5be2\u9580\u5916\uff0c\u63ee\u6d95\u5c11\u57ce\u9688\u3002", "\u5374\u8a18\u5206\u660e\u5f97\uff0c\u7336\u6301\u59d4\u66f2\u731c\u3002", "\u5e2b\u5112\u6614\u8a13\u734e\uff0c\u4ef2\u5b63\u6642\u7ae5\u5b69\u3002", "\u670d\u7fa9\u984c\u66f8\u7bcb\uff0c\u9080\u6b61\u6c4e\u9152\u676f\u3002", "\u8e54\u4ee4\u98a8\u96e8\u6563\uff0c\u4ecd\u8feb\u6b72\u6642\u8ff4\u3002", "\u5176\u9053\u60df\u6b63\u76f4\uff0c\u5176\u4eba\u4fe1\u7f8e\u5072\u3002", "\u767d\u982d\u9084\u4f5c\u5c09\uff0c\u9ec3\u7dac\u56fa\u975e\u624d\u3002", "\u53ef\u6b4e\u61f8\u86c7\u75be\uff0c\u5148\u8cbd\u554f\u9d69\u707d\u3002", "\u6545\u9109\u9589\u7aae\u58e4\uff0c\u5bbf\u8349\u751f\u5bd2\u8344\u3002", "\u96f6\u843d\u4e5d\u539f\u53bb\uff0c\u8e49\u8dce\u56db\u5e8f\u50ac\u3002", "\u66e9\u671f\u51ac\u8d08\u6a58\uff0c\u4eca\u54ed\u590f\u6210\u6885\u3002", "\u57f7\u79ae\u8ab0\u7232\u8cf5\uff0c\u5c45\u5e38\u4e0d\u5f87\u8ca1\u3002", "\u5317\u767b\u5d54\ud847\udef1\u5742\uff0c\u6771\u671b\u59d1\u8607\u81fa\u3002", "\u5929\u8def\u672c\u61f8\u7d55\uff0c\u6c5f\u6ce2\u5fa9\u6cdd\u6d04\u3002", "\u5ff5\u5b64\u5fc3\u6613\u65b7\uff0c\u8ffd\u5f80\u6068\u8271\u88c1\u3002", "\u4e0d\u9042\u537f\u5c07\u4f2f\uff0c\u5b70\u4e91\u9673\u8207\u96f7\u3002", "\u543e\u8870\u4ea6\u5982\u6b64\uff0c\u592b\u5b50\u5fa9\u4f55\u54c0\u3002"]', '诗', 'shi', '', NULL, '蜀城哭台州樂安少府 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f528586-3940-4d2a-8145-474ef8202668', '立春日侍宴內出剪綵花應制', '立春日侍宴内出剪彩花应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u66c9\u5165\u5b9c\u6625\u82d1\uff0c\u7a60\u82b3\u5410\u7981\u4e2d\u3002", "\u526a\u5200\u56e0\u88c2\u7d20\uff0c\u599d\u7c89\u7232\u958b\u7d05\u3002", "\u5f69\u7570\u9a5a\u6d41\u96ea\uff0c\u9999\u9952\u9ede\u4fbf\u98a8\u3002", "\u88c1\u6210\u8b58\u5929\u610f\uff0c\u842c\u7269\u8207\u82b1\u540c\u3002"]', '诗', 'shi', '', NULL, '立春日侍宴內出剪綵花應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0be48092-4737-4052-a441-cf232f41af7e', '春日芙蓉園侍宴應制', '春日芙蓉园侍宴应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u5fa1\u9053\u7d05\u65d7\u51fa\uff0c\u82b3\u5712\u7fe0\u8f26\u904a\u3002", "\u7e5e\u82b1\u958b\u6c34\u6bbf\uff0c\u67b6\u7af9\u8d77\u5c71\u6a13\u3002", "\u8377\u82b0\u8f15\u85b0\u5e44\uff0c\u9b5a\u9f8d\u51fa\u8ca0\u821f\u3002", "\u5be7\u77e5\u7a46\u5929\u5b50\uff0c\u7a7a\u8ce6\u767d\u96f2\u79cb\u3002"]', '诗', 'shi', '', NULL, '春日芙蓉園侍宴應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('159307b8-e963-4996-8162-ab4653a298b3', '奉和聖製人日清暉閣宴羣臣遇雪應制', '奉和圣制人日清晖阁宴群臣遇雪应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u6a13\u89c0\u7a7a\u7159\u88cf\uff0c\u521d\u5e74\u745e\u96ea\u904e\u3002", "\u82d1\u82b1\u9f4a\u7389\u6a39\uff0c\u6c60\u6c34\u4f5c\u9280\u6cb3\u3002", "\u4e03\u65e5\u7965\u5716\u5553\uff0c\u5343\u6625\u5fa1\u8cde\u591a\u3002", "\u8f15\u98db\u50b3\u7db5\u52dd\uff0c\u5929\u4e0a\u5949\u85b0\u6b4c\u3002"]', '诗', 'shi', '', NULL, '奉和聖製人日清暉閣宴羣臣遇雪應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7df81720-68ee-4257-9536-d0685cce5e26', '奉和七夕宴兩儀殿應制', '奉和七夕宴两仪殿应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u9748\u5a9b\u4e58\u79cb\u767c\uff0c\u4ed9\u88dd\u8b66\u591c\u50ac\u3002", "\u6708\u5149\u7aba\u6b32\u6e21\uff0c\u6cb3\u8272\u8fa8\u61c9\u4f86\u3002", "\u6a5f\u77f3\u5929\u6587\u5beb\uff0c\u91dd\u6a13\u5fa1\u8cde\u958b\u3002", "\u7aca\u89c0\u68f2\u9ce5\u81f3\uff0c\u7591\u5411\u9d72\u6a4b\u8ff4\u3002"]', '诗', 'shi', '', NULL, '奉和七夕宴兩儀殿應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc67c445-07f7-4832-b519-86868d613ce3', '奉和九日幸臨渭亭登高應制得時字', '奉和九日幸临渭亭登高应制得时字', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u5609\u6703\u5b9c\u9577\u65e5\uff0c\u9ad8\u7b75\u9806\u52d5\u6642\u3002", "\u66c9\u5149\u96f2\u5916\u6d17\uff0c\u6674\u8272\u96e8\u9918\u6ecb\u3002", "\u964d\u9db4\u56e0\u97f6\u5fb7\uff0c\u5439\u82b1\u5165\u5fa1\u8a5e\u3002", "\u9858\u966a\u967d\u6578\u7bc0\uff0c\u5104\u842c\u4e5d\u79cb\u671f\u3002"]', '诗', 'shi', '', NULL, '奉和九日幸臨渭亭登高應制得時字 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ca540c1-3bfa-4b0a-bc27-ac5fd7cde86f', '游禁苑幸臨渭亭遇雪應制', '游禁苑幸临渭亭遇雪应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u5e73\u660e\u655e\u5e1d\u5c45\uff0c\u9730\u96ea\u4e0b\u51cc\u865b\u3002", "\u5beb\u6708\u542b\u73e0\u7db4\uff0c\u5f9e\u98a8\u8584\u7dba\u758f\u3002", "\u5e74\u9a5a\u82b1\u7d6e\u65e9\uff0c\u6625\u591c\u7ba1\u5f26\u521d\u3002", "\u5df2\u5c6c\u96f2\u5929\u5916\uff0c\u6b23\u627f\u9708\u6fa4\u9918\u3002"]', '诗', 'shi', '', NULL, '游禁苑幸臨渭亭遇雪應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df411b69-4327-4ab0-81cc-1bdca8b6ad83', '奉和送金城公主適西蕃應制', '奉和送金城公主适西蕃应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u5e1d\u5973\u51fa\u5929\u6d25\uff0c\u548c\u620e\u8f49\u7f7d\u8f2a\u3002", "\u5ddd\u7d93\u65b7\u8178\u671b\uff0c\u5730\u8207\u6790\u652f\u9130\u3002", "\u594f\u66f2\u98a8\u5636\u99ac\uff0c\u929c\u60b2\u6708\u4f34\u4eba\u3002", "\u65cb\u77e5\u5043\u5175\u9769\uff0c\u9577\u662f\u6f22\u5bb6\u89aa\u3002"]', '诗', 'shi', '', NULL, '奉和送金城公主適西蕃應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b197aa21-a571-49a8-80eb-e01c503a0cfc', '奉和聖製登驪山高頂寓目應制', '奉和圣制登骊山高顶寓目应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u4ed9\u8e55\u5fa1\u5c64\u6c1b\uff0c\u9ad8\u9ad8\u7a4d\u7fe0\u5206\u3002", "\u5dd6\u8072\u4e2d\u8c37\u61c9\uff0c\u5929\u8a9e\u534a\u7a7a\u805e\u3002", "\u8c50\u6a39\u9023\u9ec3\u8449\uff0c\u51fd\u95dc\u5165\u7d2b\u96f2\u3002", "\u8056\u5716\u6062\u5b87\u7e23\uff0c\u6b4c\u8ce6\u5c0f\u6a6b\u6c7e\u3002"]', '诗', 'shi', '', NULL, '奉和聖製登驪山高頂寓目應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('431d0b6c-81af-4e69-a83b-6e1c42e56d78', '侍宴桃花園詠桃花應制', '侍宴桃花园咏桃花应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u6843\u82b1\u707c\u707c\u6709\u5149\u8f1d\uff0c\u7121\u6578\u6210\u8e4a\u9ede\u66f4\u98db\u3002", "\u7232\u898b\u82b3\u6797\u542b\u7b11\u5f85\uff0c\u9042\u540c\u6eab\u6a39\u4e0d\u8a00\u6b78\u3002"]', '诗', 'shi', '', NULL, '侍宴桃花園詠桃花應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('102e706b-89de-48c7-9a68-b6a08b25c9b5', '秋社日崇讓園宴得新字', '秋社日崇让园宴得新字', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u9cf4\u7235\u4e09\u8fb2\u7a14\uff0c\u52fe\u9f8d\u767e\u4ee3\u795e\u3002", "\u904b\u660c\u53e8\u8f14\u5f3c\uff0c\u6642\u6cf0\u559c\u9ece\u6c11\u3002", "\u6a39\u7f3a\u6c60\u5149\u8fd1\uff0c\u96f2\u958b\u65e5\u5f71\u65b0\u3002", "\u751f\u5168\u61c9\u6709\u5730\uff0c\u9577\u9858\u6a02\u4ea4\u89aa\u3002"]', '诗', 'shi', '', NULL, '秋社日崇讓園宴得新字 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c05330b-1f5e-4b8e-a7b8-bb090ae92808', '奉和魏僕射秋日還鄉有懷之作', '奉和魏仆射秋日还乡有怀之作', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u5357\u5bae\u5919\u62dc\u7f77\uff0c\u6771\u9053\u665d\u904a\u521d\u3002", "\u98f2\u991e\u50be\u51a0\u84cb\uff0c\u50b3\u547c\u554f\u91cc\u95ad\u3002", "\u6a39\u60b2\u61f8\u5292\u6240\uff0c\u6eaa\u60f3\u91e3\u749c\u9918\u3002", "\u660e\u767c\u8f1d\u5149\u81f3\uff0c\u589e\u69ae\u99df\u99ac\u8eca\u3002"]', '诗', 'shi', '', NULL, '奉和魏僕射秋日還鄉有懷之作 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20e40ff6-e0e9-4252-847c-ef59cb447495', '武[擔]山寺', '武[担]山寺', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u6b66[\u64d4]\u7368\u84bc\u7136\uff0c\u58b3\u5c71\u4e0b\u7389\u6cc9\u3002", "\u9c49\u9748\u6642\u5171\u76e1\uff0c\u9f8d\u5973\u4e8b\u540c\u9077\u3002", "\u677e\u67cf\u929c\u54c0\u8655\uff0c\u5e61\u82b1\u7a2e\u798f\u7530\u3002", "\u8a4e\u77e5\u7559\u93e1\u77f3\uff0c\u9577\u8207\u6cd5\u8f2a\u5713\u3002"]', '诗', 'shi', '', NULL, '武[擔]山寺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a38183b4-3508-4ec9-b868-b4ada737a761', '餞潞州陸長史再守汾州', '饯潞州陆长史再守汾州', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u6cb3\u5c39\u653f\u6210\u671f\uff0c\u7232\u6c7e\u6614\u6240\u63a8\u3002", "\u4e0d\u69ae\u4e09\u5165\u5730\uff0c\u9084\u7f8e\u518d\u81e8\u6642\u3002", "\u64c1\u50b3\u96f2\u521d\u5408\uff0c\u805e\u9daf\u65e5\u6b63\u9072\u3002", "\u9053\u508d\u591a\u51fa\u991e\uff0c\u5225\u6709\u540f\u6c11\u601d\u3002"]', '诗', 'shi', '', NULL, '餞潞州陸長史再守汾州 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65b7c4bd-b35c-4f56-81f0-a29f1b427a29', '餞荆州崔司馬', '饯荆州崔司马', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u8302\u79ae\u96d5\u9f8d\u6614\uff0c\u9999\u540d\u5c55\u9a65\u521d\u3002", "\u6c34\u9023\u5357\u6d77\u6f32\uff0c\u661f\u62f1\u5317\u8fb0\u5c45\u3002", "\u7a0d\u767c\u4ed9\u4eba\u5c65\uff0c\u5c07\u984c\u5225\u99d5\u8f3f\u3002", "\u660e\u5e74\u5fb5\u62dc\u5165\uff0c\u8346\u7389\u4e0d\u85cf\u8af8\u3002"]', '诗', 'shi', '', NULL, '餞荆州崔司馬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d24e38e5-b873-42f2-8f43-02ef2d6b61d0', '送吏部李侍郎東歸得歸字', '送吏部李侍郎东归得归字', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u964c\u4e0a\u6709\u5149\u8f1d\uff0c\u62ab\u96f2\u5411\u6d1b\u757f\u3002", "\u8cde\u4f86\u69ae\u6248\u5f9e\uff0c\u5225\u81f3\u60dc\u5206\u98db\u3002", "\u6cc9\u6e9c\u542b\u98a8\u6025\uff0c\u5c71\u7159\u5e36\u65e5\u5fae\u3002", "\u8302\u66f9\u4eca\u53bb\u77e3\uff0c\u4eba\u7269\u559c\u6771\u6b78\u3002"]', '诗', 'shi', '', NULL, '送吏部李侍郎東歸得歸字 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06b6a208-f048-40c0-9f03-b076f891c028', '送光祿姚卿還都', '送光禄姚卿还都', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u6f22\u5ba4\u6709\u82f1\u53f0\uff0c\u8340\u5bb6\u5bf5\u4fca\u624d\u3002", "\u4e5d\u537f\u671d\u5df2\u5165\uff0c\u4e09\u5b50\u66ae\u540c\u4f86\u3002", "\u4e0d\u6388\u7db8\u7232\u8349\uff0c\u9084\u53f8\u9f0e\u7528\u6885\u3002", "\u5169\u4eac\u738b\u8005\u5b85\uff0c\u99df\u99ac\u65e5\u61c9\u8ff4\u3002"]', '诗', 'shi', '', NULL, '送光祿姚卿還都 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ae47935-e2df-4070-b7e0-e273ebc48549', '春晚送瑕丘田少府還任因寄洛中鏡上人', '春晚送瑕丘田少府还任因寄洛中镜上人', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u805e\u9053\u9084\u6c82\u4e0a\uff0c\u56e0\u8072\u5bc4\u6d1b\u6ff1\u3002", "\u5225\u6642\u82b1\u6b32\u76e1\uff0c\u6b78\u8655\u9152\u61c9\u6625\u3002", "\u805a\u6563\u540c\u884c\u5ba2\uff0c\u60b2\u6b61\u5c6c\u6545\u4eba\u3002", "\u5c11\u5e74\u8ffd\u6a02\u5730\uff0c\u9059\u8d08\u4e00\u9711\u5dfe\u3002"]', '诗', 'shi', '', NULL, '春晚送瑕丘田少府還任因寄洛中鏡上人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('160135e4-5dc7-46b0-8ec2-ba5430b0e05e', '送賈起居奉使入洛取圖書因便拜覲', '送贾起居奉使入洛取图书因便拜觐', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u820a\u570b\u624d\u56e0\u5730\uff0c\u7576\u671d\u53f2\u547d\u5b98\u3002", "\u907a\u6587\u5fb5\u95d5\u7c21\uff0c\u9084\u601d\u91c7\u82b3\u862d\u3002", "\u50b3\u767c\u95dc\u9580\u5019\uff0c\u89f4\u7a31\u9091\u91cc\u6b61\u3002", "\u65e9\u6301\u4eac\u526f\u5165\uff0c\u65cb\u4f47\u6d1b\u66f8\u520a\u3002"]', '诗', 'shi', '', NULL, '送賈起居奉使入洛取圖書因便拜覲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce6d8141-f62a-44e9-a533-0a88f7cce28e', '送常侍舒公歸覲', '送常侍舒公归觐', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u671d\u805e\u8b1b\u85dd\u9918\uff0c\u6668\u7701\u62dc\u6069\u521d\u3002", "\u8a13\u80c4\u5c0a\u5ea0\u5e8f\uff0c\u69ae\u89aa\u8000\u91cc\u95ad\u3002", "\u6731\u4e39\u83ef\u8f42\u9001\uff0c\u6591\u767d\u7dba\u7b75\u8212\u3002", "\u6c5f\u4e0a\u6625\u6d41\u6eff\uff0c\u9084\u61c9\u85a6\u8e8d\u9b5a\u3002"]', '诗', 'shi', '', NULL, '送常侍舒公歸覲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae418edf-29f6-4110-89d8-add12c322b15', '興州出行', '兴州出行', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u5371\u9014\u66c9\u672a\u5206\uff0c\u9a45\u99ac\u508d\u6c5f\u6fc6\u3002", "\u6ef4\u6ef4\u6ce3\u82b1\u9732\uff0c\u5fae\u5fae\u51fa\u5cab\u96f2\u3002", "\u677e\u68a2\u534a\u5410\u6708\uff0c\u863f\u7ff3\u6f38\u79fb\u66db\u3002", "\u65c5\u5ba2\u8178\u61c9\u65b7\uff0c\u541f\u733f\u66f4\u4f7f\u805e\u3002"]', '诗', 'shi', '', NULL, '興州出行 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f752d20-1dce-4bbd-a5fc-0d15970f2c70', '邊秋薄暮', '边秋薄暮', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u6d77\u5916\u79cb\u9df9\u64ca\uff0c\u971c\u524d\u65c5\u96c1\u6b78\u3002", "\u908a\u98a8\u601d\u979e\u9f13\uff0c\u843d\u65e5\u6158\u65cc\u9ebe\u3002", "\u6d66\u6697\u6f01\u821f\u5165\uff0c\u5ddd\u9577\u7375\u9a0e\u7a00\u3002", "\u5ba2\u60b2\u9022\u8584\u66ae\uff0c\u6cc1\u4e43\u4e8b\u620e\u6a5f\u3002"]', '诗', 'shi', '', NULL, '邊秋薄暮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63c36dcb-3ef4-4ce3-b03a-e3ec1394fd01', '曉發方騫驛', '晓发方骞驿', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u50b3\u7f6e\u9060\u5c71\u8e4a\uff0c\u9f8d\u937e\u8e74\u6f97\u6ce5\u3002", "\u7247\u9670\u5e38\u4f5c\u96e8\uff0c\u5fae\u7167\u5df2\u751f\u9713\u3002", "\u9b22\u9aea\u6101\u6c1b\u63db\uff0c\u5fc3\u60c5\u96aa\u8def\u8ff7\u3002", "\u65b9\u77e5\u5411\u8700\u8005\uff0c\u504f\u8b58\u5b50\u898f\u557c\u3002"]', '诗', 'shi', '', NULL, '曉發方騫驛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a62f9110-f7b5-4972-b3a4-3d111557335e', '經三泉路作', '经三泉路作', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u4e09\u6708\u677e\u4f5c\u82b1\uff0c\u6625\u884c\u65e5\u6f38\u8cd2\u3002", "\u7af9\u969c\u5c71\u9ce5\u8def\uff0c\u85e4\u8513\u91ce\u4eba\u5bb6\u3002", "\u900f\u77f3\u98db\u6881\u4e0b\uff0c\u5c0b\u96f2\u7d55\u78f4\u659c\u3002", "\u6b64\u4e2d\u8ab0\u8207\u6a02\uff0c\u63ee\u6d95\u8a9e\u5e74\u83ef\u3002"]', '诗', 'shi', '', NULL, '經三泉路作 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c61d3f0-f9c9-4a21-83bc-91a2b4eb26c2', '故高安大長公主挽詞', '故高安大长公主挽词', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u5f64\u7ba1\u627f\u5e2b\u8a13\uff0c\u9752\u572d\u5099\u79ae\u5bb9\u3002", "\u5b5f\u5b6b\u5bb6\u4ee3\u5bf5\uff0c\u5143\u5973\u570b\u671d\u5c01\u3002", "\u67d4\u8ecc\u984c\u8c9e\u9806\uff0c\u9591\u898f\u8ce6\u8085\u96cd\u3002", "\u5be7\u77e5\u843d\u7167\u76e1\uff0c\u971c\u5439\u5165\u60b2\u677e\u3002"]', '诗', 'shi', '', NULL, '故高安大長公主挽詞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65ba98bf-17d0-4920-888c-d7b7ea34cd0f', '贈司徒豆盧府君挽詞', '赠司徒豆卢府君挽词', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u5bf5\u8d08\u8ffd\u80e1\u5ee3\uff0c\u89aa\u81e8\u6bd4\u8cc0\u5faa\u3002", "\u5e7e\u805e\u6295\u5292\u5ba2\uff0c\u591a\u6703\u670d\u7de6\u4eba\u3002", "\u8349\u9589\u58b3\u5c07\u53e4\uff0c\u677e\u9670\u5730\u4e0d\u6625\u3002", "\u4e8c\u9675\u7336\u53ef\u671b\uff0c\u5b58\u6b7f\u6709\u5fe0\u81e3\u3002"]', '诗', 'shi', '', NULL, '贈司徒豆盧府君挽詞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11c519f0-d28d-4991-a888-23b3b51a2aa4', '故右散騎常侍舒國公褚公挽詞', '故右散骑常侍舒国公褚公挽词', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u967d\u7fdf\u758f\u8c50\u69cb\uff0c\u81e8\u5e73\u6f14\u6176\u6e90\u3002", "\u5b78\u7b75\u5c0a\u6388\u51e0\uff0c\u5112\u670d\u5bf5\u4e58\u8ed2\u3002", "\u5be9\u8aed\u7559\u4e2d\u5bc6\uff0c\u958b\u9673\u8207\u4e0a\u8a00\u3002", "\u5f82\u6689\u4e00\u4e0d\u501f\uff0c\u7a7a\u6709\u8cdc\u6771\u5712\u3002"]', '诗', 'shi', '', NULL, '故右散騎常侍舒國公褚公挽詞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('368efa80-0488-4b26-b662-e16c5ddb2392', '奉和初春幸太平公主南莊應制', '奉和初春幸太平公主南庄应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u4e3b\u7b2c\u5c71\u9580\u8d77\u705e\u5ddd\uff0c\u5bb8\u904a\u98a8\u666f\u5165\u521d\u5e74\u3002", "\u9cf3\u7687\u6a13\u4e0b\u4ea4\u5929\u4ed7\uff0c\u70cf\u9d72\u6a4b\u982d\u655e\u5fa1\u7b75\u3002", "\u5f80\u5f80\u82b1\u9593\u9022\u7db5\u77f3\uff0c\u6642\u6642\u7af9\u88cf\u898b\u7d05\u6cc9\u3002", "\u4eca\u671d\u6248\u8e55\u5e73\u967d\u9928\uff0c\u4e0d\u7fa8\u4e58\u69ce\u96f2\u6f22\u908a\u3002"]', '诗', 'shi', '', NULL, '奉和初春幸太平公主南莊應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6c09a89-52ef-41fc-9a7b-73a7879b3d79', '奉和春日幸望春宮應制', '奉和春日幸望春宫应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u6771\u671b\u671b\u6625\u6625\u53ef\u6190\uff0c\u66f4\u9022\u6674\u65e5\u67f3\u542b\u7159\u3002", "\u5bae\u4e2d\u4e0b\u898b\u5357\u5c71\u76e1\uff0c\u57ce\u4e0a\u5e73\u81e8\u5317\u6597\u61f8\u3002", "\u7d30\u8349\u5fa7\u627f\u56de\u8f26\u8655\uff0c\u8f15\u82b1\u5fae\u843d\u5949\u89f4\u524d\u3002", "\u5bb8\u904a\u5c0d\u6b64\u6b61\u7121\u6975\uff0c\u9ce5\u54e2\u8072\u8072\u5165\u7ba1\u7d43\u3002"]', '诗', 'shi', '', NULL, '奉和春日幸望春宮應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b92be3fe-0794-4f94-af48-4201f980535f', '人日重宴大明宮恩賜綵縷人勝應制', '人日重宴大明宫恩赐彩缕人胜应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u758f\u9f8d\u78f4\u9053\u5207\u662d\u56de\uff0c\u5efa\u9cf3\u65d7\u9580\u7e5e\u5e1d\u81fa\u3002", "\u4e03\u8449\u4ed9\u84c2\u4f9d\u6708\u5410\uff0c\u5343\u682a\u5fa1\u67f3\u62c2\u7159\u958b\u3002", "\u521d\u5e74\u7af6\u8cbc\u5b9c\u6625\u52dd\uff0c\u9577\u547d\u5148\u6d6e\u737b\u58fd\u676f\u3002", "\u662f\u65e5\u7687\u9748\u77e5\u7aca\u5e78\uff0c\u7fa3\u5fc3\u5c31\u6367\u5927\u660e\u4f86\u3002"]', '诗', 'shi', '', NULL, '人日重宴大明宮恩賜綵縷人勝應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36574aff-4df8-4f62-b800-b9de5bb03f5c', '侍宴安樂公主山莊應制', '侍宴安乐公主山庄应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u99f8\u99f8\u7fbd\u9a0e\u6b77\u57ce\u6c60\uff0c\u5e1d\u5973\u6a13\u81fa\u5411\u665a\u62ab\u3002", "\u9727\u7051\u65cc\u65d7\u96f2\u5916\u51fa\uff0c\u98a8\u56de\u5dd6\u5cab\u96e8\u4e2d\u79fb\u3002", "\u7576\u8ed2\u534a\u843d\u5929\u6cb3\u6c34\uff0c\u7e5e\u5f91\u5168\u4f4e\u6708\u6a39\u679d\u3002", "\u7c2b\u9f13\u5bb8\u904a\u966a\u5bb4\u65e5\uff0c\u548c\u9cf4\u96d9\u9cf3\u559c\u4f86\u5100\u3002"]', '诗', 'shi', '', NULL, '侍宴安樂公主山莊應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99eb1aa8-4fd8-4e54-8340-c0ba019478c1', '興慶池侍宴應制', '兴庆池侍宴应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u964d\u9db4\u6c60\u524d\u56de\u6b65\u8f26\uff0c\u68f2\u9e1e\u6a39\u676a\u51fa\u884c\u5bae\u3002", "\u5c71\u5149\u7a4d\u7fe0\u9059\u7591\u903c\uff0c\u6c34\u614b\u542b\u9752\u8fd1\u82e5\u7a7a\u3002", "\u76f4\u8996\u5929\u6cb3\u5782\u8c61\u5916\uff0c\u4fef\u7aba\u4eac\u5ba4\u756b\u5716\u4e2d\u3002", "\u7687\u6b61\u672a\u4f7f\u6069\u6ce2\u6975\uff0c\u65e5\u66ae\u6a13\u8239\u66f4\u8d77\u98a8\u3002"]', '诗', 'shi', '', NULL, '興慶池侍宴應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6d73f2b-66de-4a73-b974-8afeb27df095', '廣達樓下夜侍酺宴應制', '广达楼下夜侍酺宴应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u6771\u5dbd\u5c01\u5efb\u5bb4\u6d1b\u4eac\uff0c\u897f\u5889\u901a\u665a\u6703\u516c\u537f\u3002", "\u6a13\u81fa\u7d55\u52dd\u5b9c\u6625\u82d1\uff0c\u71c8\u706b\u9084\u540c\u4e0d\u591c\u57ce\u3002", "\u6b63\u89a9\u4eba\u9593\u671d\u5e02\u6a02\uff0c\u5ffd\u805e\u5929\u4e0a\u7ba1\u5f26\u8072\u3002", "\u917a\u4f86\u842c\u821e\u7fa3\u81e3\u9189\uff0c\u559c\u6234\u5343\u5e74\u8056\u4e3b\u660e\u3002"]', '诗', 'shi', '', NULL, '廣達樓下夜侍酺宴應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8efe434-9077-4f89-bf28-488c63ad157e', '龍池樂章', '龙池乐章', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u897f\u4eac\u9cf3\u90b8\u8e8d\u9f8d\u6cc9\uff0c\u4f73\u6c23\u4f11\u5149\u93ae\u5728\u5929\u3002", "\u8ed2\u540e\u9727\u5716\u4eca\u5df2\u5f97\uff0c\u79e6\u738b\u6c34\u5292\u6614\u5e38\u50b3\u3002", "\u6069\u9b5a\u4e0d\u5165\u6606\u660e\u91e3\uff0c\u745e\u9db4\u9577\u5982\u592a\u6db2\u4ed9\u3002", "\u9858\u4f8d\u5de1\u904a\u540c\u820a\u91cc\uff0c\u66f4\u805e\u7c2b\u9f13\u6fdf\u6a13\u8239\u3002"]', '诗', 'shi', '', NULL, '龍池樂章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79b30853-6c81-403a-a561-d2a06836882b', '扈從鄠杜間奉呈刑部尚書舅崔黃門馬常侍', '扈从鄠杜间奉呈刑部尚书舅崔黄门马常侍', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u7fe0\u8f26\u7d05\u65d7\u51fa\u5e1d\u4eac\uff0c\u9577\u694a\u9120\u675c\u6614\u77e5\u540d\u3002", "\u96f2\u5c71\u4e00\u4e00\u770b\u7686\u7f8e\uff0c\u7af9\u6a39\u856d\u856d\u756b\u4e0d\u6210\u3002", "\u7fbd\u9a0e\u5c07\u904e\u6301\u8882\u62c2\uff0c\u9999\u8eca\u6b32\u5ea6\u6372\u7c3e\u884c\u3002", "\u6f22\u5bb6\u66fe\u8349\u5de1\u904a\u8ce6\uff0c\u4f55\u4f3c\u4eca\u4f86\u61c9\u8056\u660e\u3002"]', '诗', 'shi', '', NULL, '扈從鄠杜間奉呈刑部尚書舅崔黃門馬常侍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b3c9272-1897-44f9-bd65-efa4d09f435b', '景龍觀送裴士曹', '景龙观送裴士曹', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u6614\u65e5\u5617\u805e\u516c\u4e3b\u7b2c\uff0c\u4eca\u6642\u8b8a\u4f5c\u5217\u4ed9\u5bb6\u3002", "\u6c60\u508d\u5750\u5ba2\u7a7f\u53e2\u7be0\uff0c\u6a39\u4e0b\u904a\u4eba\u6383\u843d\u82b1\u3002", "\u96e8\u96ea\u9577\u7591\u5411\u51fd\u8c37\uff0c\u5c71\u6cc9\u76f4\u4f3c\u5230\u6d41\u6c99\u3002", "\u541b\u9084\u6d1b\u9091\u5206\u660e\u8a18\uff0c\u6b64\u8655\u540c\u4f86\u95b1\u6b72\u83ef\u3002"]', '诗', 'shi', '', NULL, '景龍觀送裴士曹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d73fbb46-ff55-4a4f-b437-5a4478a934ca', '春晚紫微省直寄內', '春晚紫微省直寄内', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u76f4\u7701\u6e05\u83ef\u63a5\u5efa\u7ae0\uff0c\u5411\u4f86\u7121\u4e8b\u65e5\u7336\u9577\u3002", "\u82b1\u9593\u71d5\u5b50\u68f2\u9cf7\u9d72\uff0c\u7af9\u4e0b\u9d77\u96db\u7e5e\u9cf3\u7687\u3002", "\u5167\u53f2\u901a\u5bb5\u627f\u7d2b\u8aa5\uff0c\u4e2d\u4eba\u843d\u665a\u611b\u7d05\u599d\u3002", "\u5225\u96e2\u4e0d\u6163\u7121\u7aae\u61b6\uff0c\u83ab\u8aa4\u537f\u537f\u5b78\u592a\u5e38\u3002"]', '诗', 'shi', '', NULL, '春晚紫微省直寄內 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53a7b4d1-3328-4002-b75e-29f49edae2c7', '贈彭州權別駕', '赠彭州权别驾', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u96d9\u6d41\u8108\u8108\u9326\u57ce\u958b\uff0c\u8ffd\u991e\u5e74\u5e74\u5f80\u5fa9\u5efb\u3002", "\u79ea\u9053\u6b4c\u8b20\u8fce\u534a\u523a\uff0c\u5f92\u805e\u79ae\u6578\u63d6\u4e2d\u53f0\u3002", "\u9ec3\u9daf\u6025\u56c0\u6625\u98a8\u76e1\uff0c\u6591\u99ac\u9577\u5636\u843d\u666f\u50ac\u3002", "\u83ab\u6134\u5206\u98db\u5c90\u8def\u5225\uff0c\u9084\u7576\u594f\u6700\u6396\u57a3\u4f86\u3002"]', '诗', 'shi', '', NULL, '贈彭州權別駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22eb983d-591b-4403-96a4-0d47d8a8ae6a', '寒食宴于中舍別駕兄弟宅', '寒食宴于中舍别驾兄弟宅', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u5b50\u63a8\u5c71\u4e0a\u6b4c\u9f8d\u7f77\uff0c\u5b9a\u570b\u9580\u524d\u7d50\u99df\u4f86\u3002", "\u59cb\u89a9\u5143\u6606\u93d8\u7389\u81f3\uff0c\u65cb\u805e\u5b63\u5b50\u4f69\u5200\u5efb\u3002", "\u6674\u82b1\u8655\u8655\u56e0\u98a8\u8d77\uff0c\u5fa1\u67f3\u689d\u689d\u5411\u65e5\u958b\u3002", "\u81ea\u6709\u9577\u7b75\u6b61\u4e0d\u6975\uff0c\u9084\u5c07\u7db5\u670d\u8a60\u5357\u9654\u3002"]', '诗', 'shi', '', NULL, '寒食宴于中舍別駕兄弟宅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcc1d431-4432-47c0-9e01-192be1ac7e07', '九月九日望蜀臺', '九月九日望蜀台', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u8700\u738b\u671b\u8700\u820a\u81fa\u524d\uff0c\u4e5d\u65e5\u5206\u660e\u898b\u4e00\u5ddd\u3002", "\u5317\u6599\u9109\u95dc\u65b9\u81ea\u6b64\uff0c\u5357\u8fad\u57ce\u90ed\u5fa9\u4f9d\u7136\u3002", "\u9752\u677e\u7e6b\u99ac\u6522\u5dd6\u7554\uff0c\u9ec3\u83ca\u7559\u4eba\u7c4d\u9053\u908a\u3002", "\u81ea\u6614\u767b\u81e8\u6e6e\u6ec5\u76e1\uff0c\u7368\u805e\u5fe0\u5b5d\u5169\u80fd\u50b3\u3002"]', '诗', 'shi', '', NULL, '九月九日望蜀臺 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('faf2b068-c36d-455c-b6b9-2564b888dabc', '奉和晦日幸昆明池應制', '奉和晦日幸昆明池应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u708e\u66c6\u4e8b\u908a\u9672\uff0c\u6606\u660e\u59cb\u947f\u6c60\u3002", "\u8c6b\u904a\u5149\u5f8c\u8056\uff0c\u5f81\u6230\u7f77\u524d\u898f\u3002", "\u973d\u8272\u6e05\u73cd\u5b87\uff0c\u5e74\u82b3\u5165\u9326\u9642\u3002", "\u5fa1\u676f\u862d\u85a6\u8449\uff0c\u4ed9\u4ed7\u67f3\u4ea4\u679d\u3002", "\u4e8c\u77f3\u5206\u6cb3\u7009\uff0c\u96d9\u73e0\u4ee3\u6708\u79fb\u3002", "\u5fae\u81e3\u6bd4\u7fd4\u6cf3\uff0c\u6069\u5ee3\u81ea\u7121\u6daf\u3002"]', '诗', 'shi', '', NULL, '奉和晦日幸昆明池應制 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fb13e75-afcd-4f2a-b32b-882fe049f6a3', '奉和聖製幸禮部尚書竇希玠宅應制', '奉和圣制幸礼部尚书窦希玠宅应制', c31812a1-6251-4f50-8131-7eaa19122f40, '唐', '["\u5c1a\u66f8\u5217\u4faf\u7b2c\uff0c\u5916\u621a\u8fd1\u81e3\u5bb6\u3002", "\u98db\u68df\u81e8\u9752\u7dba\uff0c\u8ff4\u8f3f\u8f49\u7fe0\u83ef\u3002", "\u65e5\u4ea4\u7576\u6236\u6a39\uff0c\u6cc9\u6f3e\u6eff\u6c60\u82b1\u3002", "\u5713\u9802\u5716\u5d69\u77f3\uff0c\u65b9\u6d41\u64c1\u9b4f\u6c99\u3002", "\u8c6b\u904a\u4eca\u807d\u5c65\uff0c\u4f8d\u5f9e\u6614\u9cf4\u7b33\u3002", "\u81ea\u6709\u5929\u6587\u964d\uff0c\u7121\u52de\u8a2a\u6d77\u69ce\u3002"]', '诗', 'shi', '', NULL, '奉和聖製幸禮部尚書竇希玠宅應制 shi');